import java.util.Arrays;
import java.util.Objects;
class Person { private String firstName,lastName,gender; Person(String f,String l,String g){firstName=f;lastName=l;gender=g;} public String getFirstName(){return firstName;} public void setFirstName(String v){firstName=v;} public String getLastName(){return lastName;} public void setLastName(String v){lastName=v;} public String getGender(){return gender;} public void setGender(String v){gender=v;} public String toString(){return firstName+" "+lastName+" ("+gender+")";} public boolean equals(Person p){return p!=null&&Objects.equals(firstName,p.firstName)&&Objects.equals(lastName,p.lastName)&&Objects.equals(gender,p.gender);} }
class Teacher extends Person { private String department; private String[] courses; Teacher(String f,String l,String g,String d,String[] c){super(f,l,g);department=d;courses=c.clone();} public String getDepartment(){return department;} public void setDepartment(String d){department=d;} public String[] getCourses(){return courses.clone();} public void setCourses(String[] c){courses=c.clone();} public String toString(){return super.toString()+", department="+department+", courses="+Arrays.toString(courses);} public boolean equals(Teacher t){return t!=null&&super.equals(t)&&Objects.equals(department,t.department)&&Arrays.equals(courses,t.courses);} }
class Student extends Person { private String studentId; Student(String f,String l,String g,String id){super(f,l,g);studentId=id;} public String getStudentId(){return studentId;} public void setStudentId(String id){studentId=id;} public String toString(){return super.toString()+", studentId="+studentId;} public boolean equals(Student s){return s!=null&&super.equals(s)&&Objects.equals(studentId,s.studentId);} }
class PhdStudent extends Student { private String department; private String[] courses; PhdStudent(String f,String l,String g,String id,String d,String[] c){super(f,l,g,id);department=d;courses=c.clone();} public String getDepartment(){return department;} public void setDepartment(String d){department=d;} public String[] getCourses(){return courses.clone();} public void setCourses(String[] c){courses=c.clone();} public String toString(){return super.toString()+", department="+department+", courses="+Arrays.toString(courses);} public boolean equals(PhdStudent p){return p!=null&&super.equals(p)&&Objects.equals(department,p.department)&&Arrays.equals(courses,p.courses);} }
public class Task08PersonInheritance { public static void main(String[] args){Person p=new Person("Ali","Mammadov","male");Teacher t=new Teacher("Leyla","Aliyeva","female","CS",new String[]{"Java","OOP"});Student s=new Student("Murad","Hasanov","male","S123");PhdStudent d=new PhdStudent("Aysel","Karimova","female","P456","CS",new String[]{"AI"});System.out.println(p);System.out.println(t);System.out.println(s);System.out.println(d);System.out.println(p.equals(new Person("Ali","Mammadov","male")));} }
